const getExport = `-- name: GetExport :one
SELECT e.id, e.format, e.include_raw, e.created_at, e.finished_at, e.expires_at, e.size_bytes,
  (CASE WHEN e.finished_at IS NOT NULL THEN 'done'
        WHEN j.status IN ('queued', 'running') THEN j.status
        ELSE 'failed' END)::text AS status
FROM exports e LEFT JOIN jobs j ON j.id = e.job_id
WHERE e.id = $1 AND e.user_id = $2
`

type GetExportParams struct {
	ID     uuid.UUID
	UserID uuid.UUID
}

type GetExportRow struct {
	ID         uuid.UUID
	Format     string
	IncludeRaw bool
	CreatedAt  time.Time
	FinishedAt *time.Time
	ExpiresAt  *time.Time
	SizeBytes  *int64
	Status     string
}

// Status comes from the job until the export finishes; a job that is gone or gave up is failed.
func (q *Queries) GetExport(ctx context.Context, arg GetExportParams) (GetExportRow, error) {
	row := q.db.QueryRow(ctx, getExport, arg.ID, arg.UserID)
	var i GetExportRow
	err := row.Scan(
		&i.ID,
		&i.Format,
		&i.IncludeRaw,
		&i.CreatedAt,
		&i.FinishedAt,
		&i.ExpiresAt,
		&i.SizeBytes,
		&i.Status,
	)
	return i, err
}

