const useExportToken = `-- name: UseExportToken :one
UPDATE exports SET token_used_at = now()
WHERE id = $1 AND user_id = $2 AND token_hash = $3 AND token_used_at IS NULL
  AND token_expires_at > now() AND expires_at > now()
RETURNING blob_sha256, size_bytes
`

type UseExportTokenParams struct {
	ID        uuid.UUID
	UserID    uuid.UUID
	TokenHash []byte
}

type UseExportTokenRow struct {
	BlobSha256 []byte
	SizeBytes  *int64
}

// Single use: the first download with the current, unexpired token wins.
func (q *Queries) UseExportToken(ctx context.Context, arg UseExportTokenParams) (UseExportTokenRow, error) {
	row := q.db.QueryRow(ctx, useExportToken, arg.ID, arg.UserID, arg.TokenHash)
	var i UseExportTokenRow
	err := row.Scan(&i.BlobSha256, &i.SizeBytes)
	return i, err
}
